// src/pages/MarketPrices.jsx
import { useState, useEffect, useCallback } from "react";
import C from "../constants/colors";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import TrendPill from "../components/ui/TrendPill";
// Note: Leaflet imports removed from top if not used for a map in this view to save load time

// ── Tamil Nadu Districts (Aligned with Agmarknet naming) ───────────────────
const TN_DISTRICTS = [
  { district: "Chennai",         city: "Koyambedu",       mandi: "Koyambedu CMDA Market"        },
  { district: "Coimbatore",      city: "Coimbatore",      mandi: "Coimbatore Agricultural Market"},
  { district: "Madurai",         city: "Madurai",         mandi: "Mattuthavani Market"           },
  { district: "Salem",           city: "Salem",           mandi: "Salem Agricultural Market"     },
  { district: "Tiruchirappalli", city: "Trichy",          mandi: "Ariyamangalam Market"          },
  { district: "Tirunelveli",     city: "Tirunelveli",     mandi: "Tirunelveli Market"            },
  { district: "Vellore",         city: "Vellore",         mandi: "Vellore Market"                },
  { district: "Erode",           city: "Erode",           mandi: "Erode Agricultural Market"     },
  { district: "Thanjavur",       city: "Thanjavur",       mandi: "Thanjavur Rice Market"         },
  { district: "Tiruppur",        city: "Tiruppur",        mandi: "Tiruppur Market"               },
];

const CATS = ["All","Vegetable","Cereal","Pulse","Oilseed","Fruit","Spice","Plantation"];

// ── Delta Pill Component ───────────────────────────────────────────────────
function DeltaPill({ change, prevPrice }) {
  if (!change) return <span style={{ color: C.muted, fontSize: 12 }}>—</span>;
  const pct   = prevPrice > 0 ? ((change / prevPrice) * 100).toFixed(1) : "0.0";
  const isUp  = change > 0;
  const isDn  = change < 0;
  const bg    = isUp ? "#e6f9f0" : isDn ? "#fdecea" : "#f4f4f4";
  const color = isUp ? C.bg2    : isDn ? C.red     : C.muted;
  const arrow = isUp ? "▲"      : isDn ? "▼"       : "—";
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 1 }}>
      <span style={{
        display: "inline-flex", alignItems: "center", gap: 3,
        padding: "2px 8px", borderRadius: 99,
        background: bg, color, fontSize: 12, fontWeight: 600, width: "fit-content",
      }}>
        {arrow} {isUp ? "+" : ""}{Math.abs(change).toLocaleString()}
      </span>
      <span style={{ fontSize: 10.5, color, marginLeft: 2 }}>{isUp ? "+" : ""}{pct}%</span>
    </div>
  );
}

// ── Skeleton Loader ────────────────────────────────────────────────────────
function SkeletonRows() {
  const pulse = {
    background: `linear-gradient(90deg, ${C.bg} 25%, ${C.pale} 50%, ${C.bg} 75%)`,
    backgroundSize: "200% 100%",
    animation: "shimmer 1.4s infinite",
    borderRadius: 4, height: 13,
  };
  return Array.from({ length: 6 }).map((_, i) => (
    <div key={i} style={{
      display: "grid", gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
      padding: "13px 16px", borderBottom: `1px solid ${C.border}`, gap: 10,
    }}>
      {[70, 50, 40, 60, 50, 40, 50].map((w, j) => (
        <div key={j} style={{ ...pulse, width: `${w}%` }} />
      ))}
    </div>
  ));
}

function MarketPrices({ t, lang }) {
  const [cat, setCat] = useState("All");
  const [search, setSearch] = useState("");
  const [district, setDistrict] = useState(TN_DISTRICTS[2]); // Madurai
  const [prices, setPrices] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);

  // ── Fetch Prices from Scraper Proxy ───────────────────────────────────────
  const fetchPrices = useCallback(async (d) => {
    setLoading(true);
    setError(null);

    try {
      // Connects to upgraded proxy-server.js on port 5001[cite: 5]
      const response = await fetch(`http://localhost:5001/api/prices?district=${d.district}`);

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to fetch market data");
      }

      const data = await response.json();
      setPrices(data);
      setLastUpdate(new Date());
    } catch (err) {
      console.error("Fetch error:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPrices(district);
  }, [district, fetchPrices]);

  // ── Filtering Logic ───────────────────────────────────────────────────────
  const filtered = prices.filter(p =>
    (cat === "All" || p.category === cat) &&
    (!search || p.crop.toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <div style={{ padding: 22 }}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
        <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: 0 }}>📈 Market Prices</h1>
        <button
          onClick={() => fetchPrices(district)}
          disabled={loading}
          style={{
            padding: "7px 16px", borderRadius: 8, fontSize: 12.5,
            border: `1.5px solid ${C.border}`, background: C.white,
            cursor: loading ? "not-allowed" : "pointer", opacity: loading ? 0.6 : 1,
          }}
        >
          ↻ Refresh Data
        </button>
      </div>
      <p style={{ color: C.muted, fontSize: 13, marginBottom: 14 }}>
        Live data from Agmarknet Portal • {lastUpdate ? `Last updated: ${lastUpdate.toLocaleTimeString()}` : "Fetching..."}
      </p>

      {/* District Selector Card */}
      <Card style={{ padding: "16px", marginBottom: 14 }}>
        <div style={{ display: "flex", gap: 20, alignItems: "center" }}>
          <div>
            <label style={{ fontSize: 11, color: C.muted, fontWeight: 700, display: "block", marginBottom: 5 }}>SELECT DISTRICT</label>
            <select
              value={district.district}
              onChange={e => setDistrict(TN_DISTRICTS.find(x => x.district === e.target.value))}
              style={{ padding: "8px 12px", borderRadius: 8, border: `1.5px solid ${C.border}`, fontSize: 14, minWidth: 180 }}
            >
              {TN_DISTRICTS.map(d => <option key={d.district} value={d.district}>{d.district}</option>)}
            </select>
          </div>
          <div>
            <label style={{ fontSize: 11, color: C.muted, fontWeight: 700, display: "block", marginBottom: 5 }}>ACTIVE MANDI</label>
            <div style={{ fontSize: 14, fontWeight: 500, color: C.bg2 }}>🏪 {district.mandi}</div>
          </div>
        </div>
      </Card>

      {/* Error Handling */}
      {error && (
        <div style={{ padding: 12, background: "#fdecea", color: C.red, borderRadius: 8, marginBottom: 14, fontSize: 13 }}>
          <strong>⚠️ Connection Error:</strong> {error}. <br/>
          Ensure <code>proxy-server.js</code> is running on port 5001.
        </div>
      )}

      {/* Filters */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <input
          placeholder="Search crop..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ padding: "8px 12px", borderRadius: 8, border: `1px solid ${C.border}`, width: 200 }}
        />
        {CATS.map(c => (
          <button key={c} onClick={() => setCat(c)} style={{
            padding: "6px 14px", borderRadius: 20, fontSize: 12, cursor: "pointer",
            border: `1.5px solid ${cat === c ? C.bg2 : C.border}`,
            background: cat === c ? C.pale : C.white,
            color: cat === c ? C.bg2 : C.muted,
          }}>
            {c}
          </button>
        ))}
      </div>

      {/* Results Table */}
      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{
          display: "grid", gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
          padding: "12px 16px", background: C.pale, fontSize: 11, fontWeight: 700, color: C.text, borderBottom: `1px solid ${C.border}`
        }}>
          <span>CROP</span>
          <span>MODAL (₹/Q)</span>
          <span>PREVIOUS</span>
          <span>CHANGE</span>
          <span>MIN / MAX</span>
          <span>CATEGORY</span>
          <span>TREND</span>
        </div>

        <div style={{ maxHeight: 500, overflowY: "auto" }}>
          {loading ? <SkeletonRows /> : filtered.map((p, i) => (
            <div key={i} style={{
              display: "grid", gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
              padding: "14px 16px", borderBottom: `1px solid ${C.border}`, alignItems: "center", fontSize: 13
            }}>
              <div style={{ fontWeight: 600 }}>{p.crop}</div>
              <div style={{ fontWeight: 700 }}>₹{p.modal.toLocaleString()}</div>
              <div style={{ color: C.muted }}>₹{p.prev.toLocaleString()}</div>
              <DeltaPill change={p.change} prevPrice={p.prev} />
              <div style={{ color: C.muted, fontSize: 11 }}>₹{p.min} / ₹{p.max}</div>
              <Badge bg={C.bg} color={C.muted}>{p.category}</Badge>
              <TrendPill trend={p.change > 0 ? "up" : p.change < 0 ? "down" : "flat"} />
            </div>
          ))}
          {!loading && filtered.length === 0 && (
            <div style={{ padding: 40, textAlign: "center", color: C.muted }}>No data found for this district.</div>
          )}
        </div>
      </Card>

      <style>{`
        @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
      `}</style>
    </div>
  );
}

export default MarketPrices;
